//! Shell glyph drawing. Every widget glyph name resolves to a vendored
//! Lucide SVG (`ux/shared/lucide_icons.zig`, generated by
//! `scripts/gen_lucide_icons.py`) and is rasterised through the shared SVG
//! renderer with its own per-(icon, px) surface cache.
//!
//! The Material Symbols font is no longer part of the Zig shell: a name with
//! no mapping draws nothing and returns false, so callers fall back to their
//! own primitives instead of leaking a literal ligature word.
//!
//! The module keeps its old path and `draw` signature because every widget
//! bank (bluetooth, battery, media, volume, overview, taskbar, weather card)
//! already funnels its glyph names through here.

const std = @import("std");
const cairo = @import("../../wl/buffer/shm.zig").cairo;
const svg_icons = @import("../../ux/shared/svg_icons.zig");

/// Draw the icon for material glyph `name`, centred on (cx, cy), `px`
/// pixels tall, tinted (r, g, b, a). Returns false when the name has no
/// Lucide mapping or rasterisation failed.
pub fn draw(
    cr: ?*cairo.cairo_t,
    name: []const u8,
    cx: f64,
    cy: f64,
    px: f64,
    r: f64,
    g: f64,
    b: f64,
    a: f64,
) bool {
    return svg_icons.draw(cr, name, cx, cy, px, r, g, b, a, false);
}

test "material glyph: empty and unmapped names paint nothing" {
    const t = std.testing;
    try t.expect(!draw(null, "", 0, 0, 18, 1, 1, 1, 1));
    try t.expect(!draw(null, "pause", 0, 0, 18, 1, 1, 1, 1));

    const surf = cairo.cairo_image_surface_create(cairo.CAIRO_FORMAT_ARGB32, 32, 32);
    defer cairo.cairo_surface_destroy(surf);
    const cr = cairo.cairo_create(surf);
    defer cairo.cairo_destroy(cr);
    try t.expect(!draw(cr, "definitely-not-a-glyph", 16, 16, 18, 1, 1, 1, 1));
    try t.expect(draw(cr, "pause", 16, 16, 18, 1, 1, 1, 1));
    try t.expect(cairo.cairo_status(cr) == cairo.CAIRO_STATUS_SUCCESS);
}
